<?php require "includes.php"; $q=$_GET["q"]??"";$div=$_GET["divisi"]??"";$status=$_GET["status"]??"";$sql="SELECT * FROM program_kerja WHERE 1";$params=[];if($q){$sql.=" AND (nama LIKE ? OR deskripsi LIKE ?)";$params[]="%$q%";$params[]="%$q%";}if($div){$sql.=" AND divisi=?";$params[]=$div;}if($status){$sql.=" AND status=?";$params[]=$status;}$sql.=" ORDER BY tahun DESC,id DESC";$st=$pdo->prepare($sql);$st->execute($params);$programs=$st->fetchAll(); ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Program Kerja | HMPSIF</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.6.0/css/all.min.css" rel="stylesheet"><link href="assets/css/style_modern.css" rel="stylesheet"></head><body><?php include "navbar.php"; ?><main class="section"><div class="container"><div class="eyebrow">Program Kerja</div><h1 class="section-title">Program Kerja HMTI</h1><form class="row g-2 my-4"><div class="col-md-5"><input name="q" class="form-control" placeholder="Cari program..." value="<?=e($q)?>"></div><div class="col-md-3"><select name="divisi" class="form-select"><option value="">Semua Divisi</option><?php foreach(["PSDM","Pendidikan","Kominfo","Humas","Minat dan Bakat"] as $x): ?><option <?=$div==$x?"selected":""?>><?=$x?></option><?php endforeach;?></select></div><div class="col-md-3"><select name="status" class="form-select"><option value="">Semua Status</option><?php foreach(["Selesai","Berjalan","Akan Datang"] as $x): ?><option <?=$status==$x?"selected":""?>><?=$x?></option><?php endforeach;?></select></div><div class="col-md-1"><button class="btn btn-primary w-100"><i class="fa fa-search"></i></button></div></form><div class="row g-4"><?php foreach($programs as $p): ?><div class="col-md-6 col-lg-4"><div class="card card-modern overflow-hidden"><img class="program-img" src="<?=e($p["banner"])?>"><div class="card-body p-4"><div class="d-flex justify-content-between"><span class="badge badge-soft"><?=e($p["status"])?></span><small class="text-muted"><?=$p["tahun"]?></small></div><h5 class="mt-3"><?=e($p["nama"])?></h5><p class="text-muted"><?=e($p["deskripsi"])?></p><small class="text-muted d-block mb-3"><i class="fa fa-layer-group"></i> <?=e($p["divisi"])?></small><a class="btn btn-outline-primary rounded-pill" href="detail-program.php?id=<?=$p["id"]?>">Detail</a></div></div></div><?php endforeach;?></div></div></main><?php include "footer.php"; ?></body></html>